-- ISOLATED QA ONLY. Contains no production user data.
create role anon nologin;create role authenticated nologin;create role service_role nologin bypassrls;
create schema auth;create schema storage;create schema qa;
create table auth.users(id uuid primary key,email text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema public,auth,storage to anon,authenticated,service_role;
grant execute on function auth.uid() to anon,authenticated,service_role;
create table public."efg_activities"("student_id" uuid not null default gen_random_uuid(),"activity_day" date not null default current_date,"steps" integer default null,"exercise_minutes" integer default null,"kind" text default null,"walking_pace" text default null,"walking_height_cm" numeric default null,"walking_weight_kg" numeric default null,"walking_distance_km" numeric default null,"walking_duration_minutes" integer default null,"walking_avg_heart_rate_bpm" integer default null);
